// dsw003-classify-drift (Ticket B7)
// Compare Linear issue states against the completion-marker set.
// Emits a single item: { drift_count, missing_marker, stale_linear, scanned, scan_ts }.
const fs = require('fs');
const CP_PATH = '/miru-data/cc_completion_log.jsonl';
const MAX_CP = 1000;

function readTail(p, n) {
  if (!fs.existsSync(p)) return [];
  const lines = fs.readFileSync(p, 'utf8').split(/\r?\n/).filter(l => l.trim());
  return lines.slice(-n);
}

function parseRows(lines) {
  const out = [];
  for (const l of lines) { try { out.push(JSON.parse(l)); } catch (_e) {} }
  return out;
}

// Build the marker set: ticket_ids that have at least one CONFIRMED_WORKING marker.
const cpRows = parseRows(readTail(CP_PATH, MAX_CP));
const marked = new Set();
for (const r of cpRows) {
  const tid = String(r.ticket_id || '').trim();
  if (!tid || tid.toLowerCase() === 'null') continue;
  if (r.status === 'CONFIRMED_WORKING') marked.add(tid);
}

// Pull issues from the Linear response. The API put them under team.issues.nodes.
const resp = $input.first().json || {};
const data = resp.data || {};
const team = data.team || {};
const nodes = (team.issues && team.issues.nodes) || [];

// State type buckets — Linear uses canonical type strings.
const DONE_LIKE = new Set(['completed']); // Done
const REVIEW_LIKE = new Set(['started']);  // In Progress, In Review (both started in Linear's typing)
// Note: Linear distinguishes Done (completed) from In Review only by name, not by type.
// We classify by name explicitly so we don't conflate "In Progress" with "In Review".

const missing = [];
const stale = [];
for (const issue of nodes) {
  const tid = String(issue.identifier || '').trim();
  if (!tid) continue;
  const stateName = String((issue.state && issue.state.name) || '').trim();
  const stateType = String((issue.state && issue.state.type) || '').trim();
  const hasMarker = marked.has(tid);
  // Done OR In Review without a marker → MISSING_MARKER drift.
  if ((stateName === 'Done' || stateName === 'In Review') && !hasMarker) {
    missing.push({ ticket_id: tid, state: stateName, title: issue.title || '', updated_at: issue.updatedAt || null });
    continue;
  }
  // Todo / In Progress with an existing marker → STALE_LINEAR_STATE drift.
  if ((stateName === 'Todo' || stateName === 'In Progress') && hasMarker) {
    stale.push({ ticket_id: tid, state: stateName, title: issue.title || '', updated_at: issue.updatedAt || null });
  }
}

return [{ json: {
  scan_ts: new Date().toISOString(),
  scanned: nodes.length,
  drift_count: missing.length + stale.length,
  missing_marker: missing,
  stale_linear: stale,
}}];

// dsw004-append-log (Ticket B7)
// Append one row to /miru-data/drift_scanner_log.jsonl regardless of drift
// count. Even clean days produce a heartbeat row so we can spot scanner
// outages by absence (no row for >36h means the scheduled task failed).
const fs = require('fs');
const LOG_PATH = '/miru-data/drift_scanner_log.jsonl';
const d = $input.item.json;
const row = {
  ts: d.scan_ts,
  scanned: d.scanned,
  drift_count: d.drift_count,
  missing_marker: (d.missing_marker || []).map(x => x.ticket_id),
  stale_linear: (d.stale_linear || []).map(x => x.ticket_id),
};
try {
  fs.appendFileSync(LOG_PATH, JSON.stringify(row) + '\n');
} catch (e) {
  // Don't break the workflow if disk is unavailable — log the failure in the
  // returned item so the operator sees it via execution history.
  return { json: { ...d, _log_write_error: e.message } };
}
return { json: d };

// dsw006-build-message (Ticket B7)
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const d = $input.item.json;
const lines = ['\u26A0\uFE0F <b>Linear drift detected</b> (' + d.drift_count + ' mismatches across ' + d.scanned + ' open issues)'];
if (Array.isArray(d.missing_marker) && d.missing_marker.length) {
  lines.push('');
  lines.push('<b>Missing completion marker:</b>');
  for (const m of d.missing_marker.slice(0, 20)) {
    lines.push('\u2022 ' + esc(m.ticket_id) + ' (' + esc(m.state) + ') \u2014 ' + esc((m.title || '').slice(0, 60)));
  }
  if (d.missing_marker.length > 20) lines.push('\u2026 and ' + (d.missing_marker.length - 20) + ' more');
}
if (Array.isArray(d.stale_linear) && d.stale_linear.length) {
  lines.push('');
  lines.push('<b>Marker exists but Linear state is stale:</b>');
  for (const m of d.stale_linear.slice(0, 20)) {
    lines.push('\u2022 ' + esc(m.ticket_id) + ' (' + esc(m.state) + ') \u2014 ' + esc((m.title || '').slice(0, 60)));
  }
  if (d.stale_linear.length > 20) lines.push('\u2026 and ' + (d.stale_linear.length - 20) + ' more');
}
lines.push('');
lines.push('Run <code>vp_ops_verify_ticket</code> on each, then either move Linear state or write the missing marker.');
return { json: { telegram_body: { chat_id: $env.TELEGRAM_CHAT_ID, text: lines.join('\n'), parse_mode: 'HTML', disable_notification: false } } };
